package goldenfixtures

import (
	"archive/zip"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// mediaFixtures are committed under testdata/media and regenerated by the
// gen_fixtures.sh script beside them, which needs ffmpeg. Real encoder output is
// the point: it carries the padding, edit lists and seek tables that a
// hand-built container would not.
var mediaFixtures = []string{
	"sample.mp4", // h264 and aac muxed together
	"silent.mp4", // video with no audio track
	"sample.mov", // the same boxes under a different extension
	"sample.mkv",
	"sample.webm",
	"sample.m4a", // audio only
	"sample.mp3",
	"sample.wav",
	"sample.flac",
	"sample.png",
	"sample.jpg",
	"sample.webp",
	"sample.bmp",
	"sample.tiff",
	"sample.avif",
	"sample.gif",    // an animation rather than a still
	"truncated.mp4", // a header that stops mid-box
}

func SetupMediaFixture(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()

	for _, name := range mediaFixtures {
		data, err := os.ReadFile(filepath.Join("testdata", "media", name))
		if err != nil {
			t.Fatalf("read fixture %s: %v", name, err)
		}
		if err := os.WriteFile(filepath.Join(dir, name), data, 0644); err != nil {
			t.Fatalf("write fixture %s: %v", name, err)
		}
	}

	writeFile(t, dir, "notes.txt", "beside the media\n", 0644)
	createMediaZip(t, filepath.Join(dir, "media.zip"))

	// A copy with the suffix removed, and one with the wrong suffix, so that what
	// the header says can be told apart from what the name claims.
	copyFixture(t, dir, "sample.mkv", "suffixless")
	copyFixture(t, dir, "sample.png", "mislabelled.jpg")
	writeFile(t, dir, "notes", "suffixless and not media at all\n", 0644)

	return dir
}

// SetupMediaLookalikeFixture holds text files that a name or a first few bytes
// make resemble media, and a real image under an alternative extension. It is
// kept apart from SetupMediaFixture so the directory golden there stays put.
func SetupMediaLookalikeFixture(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()

	// "BM" is a bitmap's magic, but here it starts a sentence.
	writeFile(t, dir, "bm25", "BM25 notes on ranking\nscore = idf * tf\n", 0644)
	// A Git LFS pointer checked out without the filter: text under an image name.
	writeFile(t, dir, "x.png", "version https://git-lfs.github.com/spec/v1\n"+
		"oid sha256:4d7a214614ab2935c943f9e0ff69d22eadbb8f32b1258daaa5e2ca24d17e2393\n"+
		"size 12345\n", 0644)
	copyFixture(t, dir, "sample.tiff", "x.tif")
	// An image with no name to go on, as a URL or stdin often arrives.
	copyFixture(t, dir, "sample.png", "avatar")
	// Binary that starts with a weak magic but is not the format it suggests.
	writeFile(t, dir, "counts.dat", "BM\xd2\x04"+strings.Repeat("\x00", 60), 0644)
	writeFile(t, dir, "data.bin", "\x00\x00\x01\x00\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b"+
		"\x0c\x0d\x0e\x0f\x10\x11\x12\x13\x14\x15\x16\x17", 0644)

	return dir
}

func copyFixture(t *testing.T, dir, from, to string) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "media", from))
	if err != nil {
		t.Fatalf("read fixture %s: %v", from, err)
	}
	if err := os.WriteFile(filepath.Join(dir, to), data, 0644); err != nil {
		t.Fatalf("write fixture %s: %v", to, err)
	}
}

// createMediaZip covers extraction from an archive entry, which is read through
// a different path than a file on disk.
func createMediaZip(t *testing.T, path string) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "media", "sample.wav"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}

	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("create zip: %v", err)
	}
	defer f.Close()

	w := zip.NewWriter(f)
	entry, err := w.Create("clip.wav")
	if err != nil {
		t.Fatalf("create zip entry: %v", err)
	}
	if _, err := entry.Write(data); err != nil {
		t.Fatalf("write zip entry: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("close zip: %v", err)
	}
}
